"use client";

import { useAppContext } from "@providers/AppContext";
import { useTheme } from "@providers/ThemeProvider";
import SideBarSmall from "./sidebar-small";
import SideBarExpanded from "./sidebar-expanded";

export default function SideBar() {
    const { sidebarExpanded } = useAppContext();
    const { theme } = useTheme();
    const darkTheme = theme === "dark";

    return (
        <aside
            className="shrink-0 transition-all duration-750 ease-in-out h-full w-full
            "
            style={{
                width: sidebarExpanded ? "260px" : "60px",
            }}
        >
            <div
                className="m-w-[250px] relative h-full transition-all duration-750 ease-in-out overflow-hidden
                z-100"
                style={{
                    width: sidebarExpanded ? "260px" : "60px",
                    opacity: sidebarExpanded ? 1 : 0,
                }}
            >
                <SideBarExpanded />
            </div>
            <div
                className="relative max-w-[60px] h-full overflow-hidden z-110"
                style={{ left: 0, top: 0 }}
            >
                <SideBarSmall />
            </div>
        </aside>
    );
}